### **9. MAIN GAME LOOP AND FRAME SYNCHRONIZATION**

**File:** `/f/Code/better-arc/src/app.rs` (lines 276-365)

```rust
fn window_event(&mut self, event_loop, _window_id, event) {
    match event {
        WindowEvent::RedrawRequested => {
            let current_time = state.clock.current_time_ms();

            // ... (results check)

            // Process inputs through judgment
            let inputs = state.input.drain();
            state.judge.update(current_time, &inputs, &state.input);

            // Collect hit effects from judgments
            for result in &state.judge.recent {
                if result.grade != Grade::Lost {
                    state.hit_effects.push(HitEffect {
                        lane: result.lane,
                        time_ms: result.time_ms,
                        grade: result.grade,
                    });
                    // ... hitsound
                }
            }

            // ... (score logging, combo flash)

            // Update HUD
            state.gpu.update_hud(combo, state.judge.score.score(), state.combo_flash);

            // Expire old hit effects
            state.hit_effects.retain(|e| current_time - e.time_ms < 300);

            // UPDATE NOTES (CRITICAL)
            state.gpu.update_notes(
                &state.chart,
                &state.clock,
                current_time,
                &state.judge,           // <-- pass judgment state here
                &state.hit_effects,
            );

            state.gpu.render();
            state.frame_stats.record(dt);
            state.window.request_redraw();
        }
        // ... input handling
    }
}
```

**File:** `/f/Code/better-arc/src/render/gpu.rs` (lines 391-409)

```rust
pub fn update_notes(
    &mut self,
    chart: &Chart,
    clock: &GameClock,
    current_time: Ms,
    judge: &crate::judgment::GreedyJudge,
    hit_effects: &[super::track::HitEffect],
) {
    let geo = super::track::build_note_geometry(chart, clock, current_time, judge, hit_effects);
    self.upload_mesh(&geo.taps, "note_taps");
    self.upload_mesh(&geo.holds, "note_holds");
    self.upload_mesh(&geo.arcs, "note_arcs");
    self.upload_mesh(&geo.arc_caps, "note_arc_caps");
    self.upload_mesh(&geo.sky, "note_sky");
    self.upload_mesh(&geo.lane_hits, "fx_lane");
    self.upload_mesh(&geo.hit_pure, "fx_pure");
    self.upload_mesh(&geo.hit_far, "fx_far");
}
```

**Every frame:**
1. Get current chart time
2. Process inputs and update judgments (includes hold unlocking)
3. Rebuild all note geometry (including holds with current judgment state)
4. Upload mesh data to GPU
5. Render

