4	/// Judgment grade for a single note.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
6	pub enum Grade {
7	    PureMax,  // ±25ms
8	    Pure,     // ±50ms
9	    Far,      // ±100ms
10	    Lost,     // miss (>100ms or auto-expire at 120ms)
11	}
12	
13	/// Kind of note that produced a judgment result.
14	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
15	pub enum NoteKind {
16	    Tap,
17	    HoldStart,
18	    ArcTap,
19	    HoldTick,
20	}
21	
22	/// Result of judging a note.
23	#[derive(Debug, Clone, Copy)]
24	pub struct JudgResult {
25	    pub grade: Grade,
26	    pub lane: u8,
27	    pub time_ms: Ms,
28	    pub kind: NoteKind,
29	}
