31	/// Score state.
32	#[derive(Debug, Clone)]
33	pub struct ScoreState {
34	    pub pure_max: u32,
35	    pub pure: u32,
36	    pub far: u32,
37	    pub lost: u32,
38	    pub combo: u32,
39	    pub max_combo: u32,
40	    pub total_notes: u32,
41	}
42	
43	impl ScoreState {
44	    pub fn new(total_notes: u32) -> Self {
45	        Self {
46	            pure_max: 0,
47	            pure: 0,
48	            far: 0,
49	            lost: 0,
50	            combo: 0,
51	            max_combo: 0,
52	            total_notes,
53	        }
54	    }
55	
56	    pub fn record(&mut self, grade: Grade) {
57	        match grade {
58	            Grade::PureMax => {
59	                self.pure_max += 1;
60	                self.combo += 1;
61	            }
62	            Grade::Pure => {
63	                self.pure += 1;
64	                self.combo += 1;
65	            }
66	            Grade::Far => {
67	                self.far += 1;
68	                self.combo += 1;
69	            }
70	            Grade::Lost => {
71	                self.lost += 1;
72	                self.combo = 0;
73	            }
74	        }
75	        self.max_combo = self.max_combo.max(self.combo);
76	    }
77	
78	    /// Arcaea score formula: 10,000,000 / noteCount per note.
79	    /// Max: +scorePerNote+1, Pure: +scorePerNote, Far: +half, Lost: 0.
80	    pub fn score(&self) -> u64 {
81	        if self.total_notes == 0 {
82	            return 0;
83	        }
84	        let per = 10_000_000u64 / self.total_notes as u64;
85	        self.pure_max as u64 * (per + 1)
86	            + self.pure as u64 * per
87	            + self.far as u64 * (per / 2)
88	    }
89	
90	    pub fn judged_count(&self) -> u32 {
91	        self.pure_max + self.pure + self.far + self.lost
92	    }
93	}
94	
95	/// Pending tap note waiting for judgment.
96	struct PendingTap {
97	    time: Ms,
98	    lane: u8,
99	    judged: bool,
100	}
101	
102	/// Pending hold note.
103	struct PendingHold {
104	    start: Ms,
105	    end: Ms,
106	    lane: u8,
107	    locked: bool,      // true until initial tap unlock
108	    tick_times: Vec<Ms>, // judgment tick timings
109	    next_tick: usize,    // index of next tick to process
110	}
111	
112	pub(crate) const PURE_MAX_WINDOW: Ms = 25;
113	pub(crate) const PURE_WINDOW: Ms = 50;
114	pub(crate) const FAR_WINDOW: Ms = 100;
115	pub(crate) const MISS_EXPIRE: Ms = 120;
116	
117	/// Greedy judgment engine for tap, hold, and arctap notes.
118	pub struct GreedyJudge {
119	    pending_taps: Vec<PendingTap>,
120	    pending_holds: Vec<PendingHold>,
121	    /// ArcTap (sky note): same windows as tap, any lane matches (no positional input on desktop).
122	    pending_arctaps: Vec<PendingTap>,
123	    pub score: ScoreState,
124	    /// Recent judgment results for rendering feedback (drained by renderer).
125	    pub recent: Vec<JudgResult>,
126	}
127	
128	impl GreedyJudge {
129	    pub fn new(chart: &Chart) -> Self {
130	        let mut pending_taps = Vec::new();
131	        let mut pending_holds = Vec::new();
132	        let mut total_combo = 0u32;
133	
134	        for group in &chart.groups {
135	            // Taps: 1 combo each
136	            for tap in &group.taps {
137	                pending_taps.push(PendingTap {
138	                    time: tap.time,
139	                    lane: tap.lane as u8,
140	                    judged: false,
141	                });
142	                total_combo += 1;
143	            }
144	
145	            // Holds: calculate tick timings
146	            let base_bpm = group.timings.first().map(|t| t.bpm).unwrap_or(120.0);
147	            let density = chart.timing_point_density_factor;
148	
149	            for hold in &group.holds {
150	                let bpm = base_bpm.abs(); // TODO: use BPM at hold start time
151	                let duration = hold.end - hold.start;
152	                if duration <= 0 || bpm == 0.0 {
153	                    continue;
154	                }
155	
156	                let interval = if bpm >= 255.0 {
157	                    60_000.0 / bpm / density
158	                } else {
159	                    30_000.0 / bpm / density
160	                };
161	
162	                let count = (duration as f32 / interval) as i32;
163	                let mut tick_times = Vec::new();
164	
165	                if count <= 1 {
166	                    // Single tick at midpoint
167	                    tick_times.push(hold.start + duration / 2);
168	                } else {
169	                    // First tick at start + interval, then every interval
170	                    // Total combo = count - 1 (per ArcCreate)
171	                    for i in 1..count {
172	                        tick_times.push(hold.start + (i as f32 * interval) as i32);
173	                    }
174	                }
175	
176	                total_combo += tick_times.len() as u32;
177	
178	                pending_holds.push(PendingHold {
179	                    start: hold.start,
180	                    end: hold.end,
181	                    lane: hold.lane as u8,
182	                    locked: true,
183	                    tick_times,
184	                    next_tick: 0,
185	                });
186	            }
187	
188	            // ArcTaps (sky notes on trace arcs): same judgment as taps
189	            for arc in &group.arcs {
190	                if arc.is_trace {
191	                    for sn in &arc.sky_notes {
192	                        pending_taps.push(PendingTap {
193	                            time: sn.time,
194	                            lane: 0, // sentinel: matches any lane on desktop
195	                            judged: false,
196	                        });
197	                        total_combo += 1;
198	                    }
199	                }
200	            }
201	        }
202	
203	        // Separate arctaps (lane=0) from lane taps for matching priority
204	        let pending_arctaps: Vec<PendingTap> = pending_taps
205	            .iter()
206	            .filter(|p| p.lane == 0)
207	            .map(|p| PendingTap { time: p.time, lane: 0, judged: false })
208	            .collect();
209	        pending_taps.retain(|p| p.lane != 0);
210	
211	        pending_taps.sort_by_key(|p| p.time);
212	        pending_holds.sort_by_key(|p| p.start);
213	
214	        Self {
215	            pending_taps,
216	            pending_holds,
217	            pending_arctaps,
218	            score: ScoreState::new(total_combo),
219	            recent: Vec::new(),
220	        }
221	    }
222	
223	    /// Process inputs and advance time.
224	    /// `input_mgr` provides held-lane state for hold judgment.
225	    pub fn update(&mut self, current_time: Ms, inputs: &[InputEvent], input_mgr: &InputManager) {
226	        // 1. Match tap inputs to pending taps (greedy: closest time first)
227	        let mut consumed = vec![false; inputs.len()];
228	
229	        for (ii, input) in inputs.iter().enumerate() {
230	            let mut best_idx = None;
231	            let mut best_dt = Ms::MAX;
232	
233	            for (i, p) in self.pending_taps.iter().enumerate() {
234	                if p.judged || p.lane != input.lane {
235	                    continue;
236	                }
237	                let dt = (input.time_ms - p.time).abs();
238	                if dt <= FAR_WINDOW && dt < best_dt {
239	                    best_dt = dt;
240	                    best_idx = Some(i);
241	                }
242	            }
243	
244	            if let Some(idx) = best_idx {
245	                let grade = classify(best_dt);
246	                self.pending_taps[idx].judged = true;
247	                self.score.record(grade);
248	                self.recent.push(JudgResult {
249	                    grade,
250	                    lane: input.lane,
251	                    time_ms: input.time_ms,
252	                    kind: NoteKind::Tap,
253	                });
254	                consumed[ii] = true;
255	            }
256	        }
257	
258	        // 2. Unconsumed inputs try to unlock holds
259	        let mut hold_unlocks: Vec<JudgResult> = Vec::new();
260	        for (ii, input) in inputs.iter().enumerate() {
261	            if consumed[ii] {
262	                continue;
263	            }
264	            for hold in &mut self.pending_holds {
265	                if !hold.locked || hold.lane != input.lane {
266	                    continue;
267	                }
268	                // Hold unlock window: start ± MissExpire
269	                let dt = (input.time_ms - hold.start).abs();
270	                if dt <= MISS_EXPIRE {
271	                    hold.locked = false;
272	                    hold_unlocks.push(JudgResult {
273	                        grade: classify(dt),
274	                        lane: hold.lane,
275	                        time_ms: input.time_ms,
276	                        kind: NoteKind::HoldStart,
277	                    });
278	                    break;
279	                }
280	            }
281	        }
282	        self.recent.extend(hold_unlocks);
283	
284	        // 2b. Unconsumed inputs try to match arctaps (any lane)
285	        for (ii, input) in inputs.iter().enumerate() {
286	            if consumed[ii] {
287	                continue;
288	            }
