use crate::chart::types::Ms;
use std::collections::HashMap;

/// A tap input event with lane and timestamp.
#[derive(Debug, Clone, Copy)]
pub struct InputEvent {
    pub lane: u8,     // 1-4
    pub time_ms: Ms,  // chart-time when input occurred
}

/// Collects keyboard/touch input and converts to lane-based events.
pub struct InputManager {
    /// Pending events this frame (drained by judgment engine).
    pending: Vec<InputEvent>,
    /// Currently held lanes (index 0 unused, 1-4 for lanes).
    held: [bool; 5],
    /// Maps touch ID to the lane it started on.
    active_touches: HashMap<u64, u8>,
}

impl InputManager {
    pub fn new() -> Self {
        Self {
            pending: Vec::new(),
            held: [false; 5],
            active_touches: HashMap::new(),
        }
    }

    /// Record a key press for a lane at the given chart time.
    pub fn key_down(&mut self, lane: u8, time_ms: Ms) {
        if (1..=4).contains(&lane) {
            self.pending.push(InputEvent { lane, time_ms });
            self.held[lane as usize] = true;
        }
    }

    /// Record a key release for a lane.
    pub fn key_up(&mut self, lane: u8) {
        if (1..=4).contains(&lane) {
            self.held[lane as usize] = false;
        }
    }

    /// Check if a lane is currently held.
    pub fn is_held(&self, lane: u8) -> bool {
        self.held.get(lane as usize).copied().unwrap_or(false)
    }

    /// Drain all pending events (called by judgment engine each frame).
    pub fn drain(&mut self) -> Vec<InputEvent> {
        std::mem::take(&mut self.pending)
    }

    /// Record the start of a touch contact, mapping touch_id to a lane.
    pub fn touch_start(&mut self, touch_id: u64, lane: u8, time_ms: Ms) {
        self.active_touches.insert(touch_id, lane);
        self.key_down(lane, time_ms);
    }

    /// Record the end of a touch contact, releasing the associated lane.
    pub fn touch_end(&mut self, touch_id: u64) {
        if let Some(lane) = self.active_touches.remove(&touch_id) {
            self.key_up(lane);
        }
    }
}

/// Map physical key code to lane number (1-4), or None.
/// Uses physical keys (immune to IME / keyboard layout).
/// Layout: A=Lane1, S=Lane2, D=Lane3, F=Lane4.
pub fn physical_key_to_lane(key: &winit::keyboard::PhysicalKey) -> Option<u8> {
    use winit::keyboard::{KeyCode, PhysicalKey};
    match key {
        PhysicalKey::Code(KeyCode::KeyA) => Some(1),
        PhysicalKey::Code(KeyCode::KeyS) => Some(2),
        PhysicalKey::Code(KeyCode::KeyD) => Some(3),
        PhysicalKey::Code(KeyCode::KeyF) => Some(4),
        _ => None,
    }
}

use crate::render::track::LANE_WIDTH;
use glam::{Mat4, Vec4};

/// Map screen touch coordinates to a lane number (1-4).
pub fn touch_to_lane(
    touch_x: f32,
    touch_y: f32,
    screen_width: f32,
    screen_height: f32,
    inv_view_proj: &Mat4,
) -> Option<u8> {
    let ndc_x = 2.0 * touch_x / screen_width - 1.0;
    let ndc_y = 1.0 - 2.0 * touch_y / screen_height;

    let near = *inv_view_proj * Vec4::new(ndc_x, ndc_y, 0.0, 1.0);
    let far = *inv_view_proj * Vec4::new(ndc_x, ndc_y, 1.0, 1.0);
    let near = near.truncate() / near.w;
    let far = far.truncate() / far.w;

    let dir = far - near;
    if dir.y.abs() < 1e-6 {
        return None;
    }
    let t = -near.y / dir.y;
    if t < 0.0 {
        return None;
    }
    let world_x = near.x + t * dir.x;

    let lane = ((-world_x + LANE_WIDTH * 2.5) / LANE_WIDTH).round() as i32;
    Some(lane.clamp(1, 4) as u8)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::render::camera::Camera;

    fn test_camera() -> Camera {
        Camera::arcaea_default(9.0 / 16.0, 1600.0)
    }

    #[test]
    fn touch_center_maps_to_lane_2_or_3() {
        let cam = test_camera();
        let inv = cam.inv_view_proj();
        let lane = touch_to_lane(450.0, 800.0, 900.0, 1600.0, &inv);
        assert!(lane == Some(2) || lane == Some(3), "center touch should be lane 2 or 3, got {lane:?}");
    }

    #[test]
    fn touch_lane4_roundtrip() {
        let cam = test_camera();
        let vp = cam.view_proj();
        let inv = cam.inv_view_proj();
        let world_x = crate::render::track::lane_to_x(4.0);
        let clip = vp * Vec4::new(world_x, 0.01, 0.0, 1.0);
        let ndc = clip.truncate() / clip.w;
        let sx = (ndc.x + 1.0) / 2.0 * 900.0;
        let sy = (1.0 - ndc.y) / 2.0 * 1600.0;
        let lane = touch_to_lane(sx, sy, 900.0, 1600.0, &inv);
        assert_eq!(lane, Some(4), "lane 4 center touch should map to lane 4");
    }

    #[test]
    fn touch_lane1_roundtrip() {
        let cam = test_camera();
        let vp = cam.view_proj();
        let inv = cam.inv_view_proj();
        let world_x = crate::render::track::lane_to_x(1.0);
        let clip = vp * Vec4::new(world_x, 0.01, 0.0, 1.0);
        let ndc = clip.truncate() / clip.w;
        let sx = (ndc.x + 1.0) / 2.0 * 900.0;
        let sy = (1.0 - ndc.y) / 2.0 * 1600.0;
        let lane = touch_to_lane(sx, sy, 900.0, 1600.0, &inv);
        assert_eq!(lane, Some(1), "lane 1 center touch should map to lane 1");
    }

    #[test]
    fn x_to_lane_roundtrip() {
        let cam = test_camera();
        let vp = cam.view_proj();
        let inv = cam.inv_view_proj();

        for expected_lane in 1u8..=4 {
            let world_x = crate::render::track::lane_to_x(expected_lane as f32);
            let clip = vp * Vec4::new(world_x, 0.01, 0.0, 1.0);
            let ndc = clip.truncate() / clip.w;
            let sx = (ndc.x + 1.0) / 2.0 * 900.0;
            let sy = (1.0 - ndc.y) / 2.0 * 1600.0;

            let lane = touch_to_lane(sx, sy, 900.0, 1600.0, &inv);
            assert_eq!(
                lane,
                Some(expected_lane),
                "lane_to_x({expected_lane}) -> screen ({sx:.0}, {sy:.0}) -> should map back to lane {expected_lane}"
            );
        }
    }
}

