/// Returns the visual state of a hold for rendering.
/// `is_lane_held`: whether the player is currently pressing this lane.
pub fn hold_visual_state(&self, start: Ms, lane: u8, current_time: Ms, is_lane_held: bool) -> HoldVisualState {
    for h in &self.pending_holds {
        if h.start != start || h.lane != lane {
            continue;
        }
        if h.next_tick >= h.tick_times.len() && current_time > h.end {
            return HoldVisualState::Complete;
        }
        if current_time >= h.start {
            if !h.locked && is_lane_held {
                return HoldVisualState::Active;
            }
            return HoldVisualState::Inactive;
        }
        return HoldVisualState::Approaching;
    }
    HoldVisualState::Complete
}

