fn build_hold(
    hold: &Hold,
    z1: f32,
    z2: f32,
    state: crate::judgment::HoldVisualState,
    verts: &mut Vec<Vertex>,
    idxs: &mut Vec<u32>,
) {
    use crate::judgment::HoldVisualState;
    let cx = lane_to_x(hold.lane);
    let hw = NOTE_HALF_WIDTH;

    let z_start = match state {
        HoldVisualState::Active => z1.min(0.0),
        _ => z1,
    };
    let hold_len = (z_start - z2).abs();
    if hold_len < 0.01 {
        return;
    }

    let base_alpha = match state {
        HoldVisualState::Inactive => HOLD_MAX_ALPHA * 0.55,
        _ => HOLD_MAX_ALPHA,
    };
    let alpha_front = base_alpha * note_fade_alpha(z_start);
    let alpha_back = base_alpha * note_fade_alpha(z2);
    let v_tiles = (hold_len / NOTE_WIDTH).max(1.0);

    let base = verts.len() as u32;
    verts.push(Vertex { position: [cx - hw, NOTE_Y, z_start], color: [1.0, 1.0, 1.0, alpha_front], uv: [0.0, 0.0] });
    verts.push(Vertex { position: [cx + hw, NOTE_Y, z_start], color: [1.0, 1.0, 1.0, alpha_front], uv: [1.0, 0.0] });
    verts.push(Vertex { position: [cx + hw, NOTE_Y, z2], color: [1.0, 1.0, 1.0, alpha_back], uv: [1.0, v_tiles] });
    verts.push(Vertex { position: [cx - hw, NOTE_Y, z2], color: [1.0, 1.0, 1.0, alpha_back], uv: [0.0, v_tiles] });
    idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
}

fn build_hold_head(
    hold: &Hold,
    z1: f32,
    state: crate::judgment::HoldVisualState,
    verts: &mut Vec<Vertex>,
    idxs: &mut Vec<u32>,
) {
    use crate::judgment::HoldVisualState;
    if state == HoldVisualState::Inactive {
        return;
    }
    let z = match state {
        HoldVisualState::Active => z1.min(0.0),
        _ => z1,
    };
    let cx = lane_to_x(hold.lane);
    let hw = NOTE_HALF_WIDTH;
    let depth = NOTE_BASE_DEPTH * tap_note_scale(z);
    let hd = depth * 0.5;
    let alpha = note_fade_alpha(z);
    push_quad_uv(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z + hd],
            [cx - hw, NOTE_Y, z + hd],
        ],
        [1.0, 1.0, 1.0, alpha],
        [[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]],
    );
}

