/// Build arc cap indicator.
/// - During play: cap at current arc position, size = ARC_CAP_SIZE.
/// - Before start: approach indicator at start position, growing size.
/// Source: ArcCreate Arc.Rendering.cs UpdateSegmentsAndArcCap
fn build_arc_cap(
    arc: &Arc,
    clock: &GameClock,
    current_time: Ms,
    verts: &mut Vec<Vertex>,
    idxs: &mut Vec<u32>,
) {
    let duration_ms = (arc.end - arc.start) as f32;

    if current_time >= arc.start && current_time < arc.end && duration_ms > 0.0 {
        // Active: cap follows current position on the arc
        let t = (current_time - arc.start) as f32 / duration_ms;
        let (x, y) = arc.easing.apply(arc.x1, arc.x2, arc.y1, arc.y2, t);
        let wx = arc_x_to_world(x);
        let wy = arc_y_to_world(y);
        // Cap is at z=0 (judgment line plane) since it tracks current time
        let hw = ARC_CAP_SIZE * 0.5;
        push_quad_uv(
            verts,
            idxs,
            [
                [wx - hw, wy - hw, 0.0],
                [wx + hw, wy - hw, 0.0],
                [wx + hw, wy + hw, 0.0],
                [wx - hw, wy + hw, 0.0],
            ],
            [1.0, 1.0, 1.0, ARC_CAP_ALPHA],
            [[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]],
        );
    } else if current_time < arc.start {
        // Approach: cap at arc start position, growing as it approaches
        let z = clock.time_to_z(arc.start, current_time, DROP_RATE);
        if z < -TRACK_LENGTH_FORWARD || z > TRACK_LENGTH_BACKWARD {
            return;
        }
        let approach = (1.0 - z.abs() / TRACK_LENGTH_FORWARD).clamp(0.0, 1.0);

