- [ ] **Step 1: Rewrite build_arc_body**

Replace the entire `build_arc_body` function in `src/render/track.rs` with:

```rust
fn build_arc_body(
    arc: &Arc,
    clock: &GameClock,
    current_time: Ms,
    verts: &mut Vec<Vertex>,
    idxs: &mut Vec<u32>,
) {
    let duration_ms = (arc.end - arc.start) as f32;
    if duration_ms <= 0.0 {
        return;
    }

    let num_segments = ((duration_ms / ARC_SEGMENT_MS).ceil() as usize).max(1);

    let color = if arc.is_trace {
        [0.60, 0.60, 0.70, TRACE_ALPHA_SCALAR]
    } else if arc.color == 0 {
        [0.30, 0.60, 1.00, ARC_MAX_ALPHA]
    } else {
        [1.00, 0.30, 0.50, ARC_MAX_ALPHA]
    };

    let body_width = if arc.is_trace {
        TRACE_BODY_WIDTH
    } else {
        ARC_BODY_WIDTH
    };
    let body_height = if arc.is_trace {
        ARC_BODY_HEIGHT * (TRACE_BODY_WIDTH / ARC_BODY_WIDTH)
    } else {
        ARC_BODY_HEIGHT
    };

    for i in 0..num_segments {
        let t0 = i as f32 / num_segments as f32;
        let t1 = (i + 1) as f32 / num_segments as f32;

        let (x0, y0) = arc.easing.apply(arc.x1, arc.x2, arc.y1, arc.y2, t0);
        let (x1, y1) = arc.easing.apply(arc.x1, arc.x2, arc.y1, arc.y2, t1);

        let time0 = arc.start + (duration_ms * t0) as i32;
        let time1 = arc.start + (duration_ms * t1) as i32;

        let wx0 = arc_x_to_world(x0);
        let wy0 = arc_y_to_world(y0);
        let wz0 = clock.time_to_z(time0, current_time, DROP_RATE);

        let wx1 = arc_x_to_world(x1);
        let wy1 = arc_y_to_world(y1);
        let wz1 = clock.time_to_z(time1, current_time, DROP_RATE);

        if wz0 > TRACK_LENGTH_BACKWARD && wz1 > TRACK_LENGTH_BACKWARD {
            continue;
        }
        if wz0 < -TRACK_LENGTH_FORWARD && wz1 < -TRACK_LENGTH_FORWARD {
            continue;
        }

        // Conical head: first segment front (t=0) tapers to a point
        let scale0 = if i == 0 { 0.0 } else { 1.0 };
        let hw0 = body_width * 0.5 * scale0;
        let bh0 = body_height * scale0;
        let hw1 = body_width * 0.5;
        let bh1 = body_height;

        // Cross-section vertices at each end of the segment:
        //   apex = (cx, cy + height, z)
        //   left = (cx - hw, cy, z)
        //   right = (cx + hw, cy, z)

        let v0 = t0;
        let v1 = t1;

        // Left slope face: left_0 → apex_0 → apex_1 → left_1
        let base = verts.len() as u32;
        verts.push(Vertex { position: [wx0 - hw0, wy0, wz0], color, uv: [0.0, v0] });
        verts.push(Vertex { position: [wx0, wy0 + bh0, wz0], color, uv: [0.5, v0] });
        verts.push(Vertex { position: [wx1, wy1 + bh1, wz1], color, uv: [0.5, v1] });
        verts.push(Vertex { position: [wx1 - hw1, wy1, wz1], color, uv: [0.0, v1] });
        idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);

        // Right slope face: apex_0 → right_0 → right_1 → apex_1
        let base = verts.len() as u32;
        verts.push(Vertex { position: [wx0, wy0 + bh0, wz0], color, uv: [0.5, v0] });
        verts.push(Vertex { position: [wx0 + hw0, wy0, wz0], color, uv: [1.0, v0] });
        verts.push(Vertex { position: [wx1 + hw1, wy1, wz1], color, uv: [1.0, v1] });
        verts.push(Vertex { position: [wx1, wy1 + bh1, wz1], color, uv: [0.5, v1] });
        idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);

        // Bottom face: left_0 → right_0 → right_1 → left_1
        let base = verts.len() as u32;
        verts.push(Vertex { position: [wx0 - hw0, wy0, wz0], color, uv: [0.0, v0] });
        verts.push(Vertex { position: [wx0 + hw0, wy0, wz0], color, uv: [1.0, v0] });
        verts.push(Vertex { position: [wx1 + hw1, wy1, wz1], color, uv: [1.0, v1] });
        verts.push(Vertex { position: [wx1 - hw1, wy1, wz1], color, uv: [0.0, v1] });
        idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
    }
}
```

Key changes vs current code:
- **3 quads per segment** (left slope, right slope, bottom) instead of 1 flat quad
- **Conical head**: `scale0 = 0.0` when `i == 0`, collapsing front cross-section to a point
- **Color tuning**: blue `[0.30, 0.60, 1.00]`, red `[1.00, 0.30, 0.50]` (more saturated)
- **No z=0 clipping**: segments past judgment line pass through naturally

