        verts.push(Vertex { position: [wx1, wy1 + bh, wz1], color, uv: [0.5, v1] });
        idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);

        // Bottom face
        let base = verts.len() as u32;
        verts.push(Vertex { position: [wx0 - hw, wy0, wz0], color, uv: [0.0, v0] });
        verts.push(Vertex { position: [wx0 + hw, wy0, wz0], color, uv: [1.0, v0] });
        verts.push(Vertex { position: [wx1 + hw, wy1, wz1], color, uv: [1.0, v1] });
        verts.push(Vertex { position: [wx1 - hw, wy1, wz1], color, uv: [0.0, v1] });
        idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
    }
}
